-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8821, 21, 'Regelsatz der Grundsicherung regelmäßig an Preisentwicklung anpassen (Bund)', 'Zeitnahe Anpassung verhindert reale Kaufkraftverluste wie 2022/23. Die Fortschreibung mit Mischindex und Besitzschutz besteht aber schon; eine Lücke durch zu knappe Bemessung schließt sie nicht.', 'belegt', 'https://www.bundesregierung.de/breg-de/suche/buergergeld-2025-2248000', 'bund', null, true, 'blind'),
  (8822, 21, 'Anstieg des Regelsatzes begrenzen oder Regelsatz absenken (Bund)', 'Ein niedrigerer oder langsamer steigender Regelsatz vergrößert eine Versorgungslücke eher. Für die Absenkung spricht der Inflationsüberschuss 2024; Studien sehen die Bemessung dagegen eher als zu knapp.', 'gemischt', 'https://www.boeckler.de/de/pressemitteilungen-2675-kindergrundsicherung-niveau-muesste-je-nach-alter-6-bis-30-prozent-hoeher-sein-59625.htm', 'bund', null, true, 'blind'),
  (8823, 21, 'Kindergrundsicherung einführen, die kindbezogene Leistungen bündelt (Bund)', 'Simulationen erwarten rund 2 Prozentpunkte weniger Kinderarmut, vor allem weil mehr Berechtigte Leistungen erhalten. Ohne festgelegtes Niveau bleibt die Wirkung begrenzt; Kosten und Verwaltungsumbau sind erheblich.', 'belegt', 'https://www.boeckler.de/de/boeckler-impuls-kindergrundsicherung-besser-als-nichts-58539.htm', 'bund', null, true, 'blind'),
  (8824, 21, 'Kindergeld anheben bzw. an den Kinderfreibetrag angleichen (Bund)', 'Kindergeld senkt das Armutsrisiko von Familien nachweislich, besonders bei Alleinerziehenden. Bei Grundsicherungsbezug wird es aber angerechnet, die ärmsten Familien gewinnen daher wenig; die Kosten sind hoch.', 'belegt', 'https://www.caritas.de/neue-caritas/heftarchiv/jahrgang2014/artikel/milliarden-nur-fuer-schmu--wie-familienpolitik-wirkt', 'bund', null, true, 'blind'),
  (8825, 21, 'Steuerliche Abzüge für Alleinerziehende und Familien ausweiten (Bund)', 'Entlastet Alleinerziehende mit Steuerschuld und ist leicht umsetzbar. Haushalte mit geringem Einkommen zahlen kaum Steuern und profitieren von Abzügen wenig; Steuervorteile wachsen meist mit dem Einkommen.', 'belegt', 'https://www.diw.de/de/diw_01.c.426860.de/unionsreformvorschlag_zur_familienbesteuerung__einkommensschwache_profitieren_am_wenigsten.html', 'bund', null, true, 'blind'),
  (8826, 21, 'Unterhaltsvorschuss ausweiten, Kindergeld nur teilweise anrechnen (Bund)', 'Mehr Geld für Kinder Alleinerziehender ohne Unterhalt; die Ausweitung 2017 erreichte 300.000 Kinder mehr. Dagegen: Anrechnung auf Kinderzuschlag und Bürgergeld mindert den Nettoeffekt; Bund, Länder und Kommunen tragen Kosten.', 'gemischt', 'https://www.bundesregierung.de/Content/DE/Artikel/2018/08/2018-08-22-bericht-unterhaltsvorschuss.html', 'bund', null, true, 'blind'),
  (8827, 21, 'Familienleistungen digital bündeln, Antrag vereinfachen und automatisch auszahlen (Bund)', 'Vereinfachte, vorausgefüllte oder antragslose Verfahren erhöhen die Inanspruchnahme (Studien, antraglose Familienbeihilfe in Österreich). Dagegen: Datenverknüpfung und Digitalisierung der Verwaltung brauchen Jahre.', 'belegt', 'https://www.diw.de/de/diw_01.c.699957.de/publikationen/wochenberichte/2019_49/starke_nichtinanspruchnahme_von_grundsicherung_deutet_auf_hohe_verdeckte_altersarmut.html', 'bund', null, true, 'blind')
